import numpy as np

def f(x: float) -> float:
    return x**2 + 2.0 * x

def central_difference(fun, x: float, h: float) -> float:
    if h <= 0.0:
        raise ValueError("h must be positive")
    return (fun(x + h) - fun(x - h)) / (2.0 * h)

x0 = 1.5
analytic = 2.0 * x0 + 2.0
for h in np.logspace(-1, -10, 10):
    numerical = central_difference(f, x0, h)
    print(f"h={h:.1e}, error={abs(numerical-analytic):.3e}")

def damped_pseudoinverse(J, damping=1e-3):
    J = np.asarray(J, dtype=float)
    if damping < 0:
        raise ValueError("damping must be non-negative")
    m = J.shape[0]
    return J.T @ np.linalg.solve(
        J @ J.T + damping**2*np.eye(m), np.eye(m))

